import React, { useEffect, useState } from "react";
import UsageBarChart from "./components/UsageBarChart";
import UsagePieChart from "./components/UsagePieChart";
import ActivityList from "./components/ActivityList";

export default function App() {
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  /* ---------------- FETCH SESSIONS ---------------- */
  const fetchSessions = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/analytics");
      if (!res.ok) throw new Error("Failed to fetch sessions");
      const data = await res.json();
      setSessions(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error(err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSessions();

    // Poll every 15s for missed events
    const interval = setInterval(fetchSessions, 15000);
    return () => clearInterval(interval);
  }, []);

  /* ---------------- REAL-TIME SESSION ADDITION ---------------- */
  // Example: if your Chrome extension sends new session via a window.postMessage
  useEffect(() => {
    const handleNewSession = (event) => {
      const newSession = event.data;
      // Make sure it's the right event type
      if (newSession?.type === "NEW_SESSION") {
        setSessions((prev) => [...prev, newSession.session]);
      }
    };

    window.addEventListener("message", handleNewSession);
    return () => window.removeEventListener("message", handleNewSession);
  }, []);

  /* ---------------- COMPUTE SUMMARY ---------------- */
  const summary = sessions.reduce((acc, session) => {
    const existing = acc.find((item) => item.url === session.url);
    if (existing) {
      existing.totalTime += session.timeSpent;
    } else {
      acc.push({ url: session.url, totalTime: session.timeSpent });
    }
    return acc;
  }, []);

  /* ---------------- KPI CALCULATIONS ---------------- */
  const totalTime = summary.reduce((acc, item) => acc + (item.totalTime || 0), 0);
  const hours = Math.floor(totalTime / 60);
  const mins = totalTime % 60;

  const totalSites = summary.length;

  const mostUsedSite =
    summary.length > 0
      ? summary.reduce((max, item) =>
          (item.totalTime || 0) > (max.totalTime || 0) ? item : max
        ).url
      : "N/A";

  const totalSessions = sessions.length;

  /* ---------------- SAFE RENDER ---------------- */
  if (loading)
    return <p style={{ textAlign: "center", marginTop: "50px" }}>Loading dashboard...</p>;

  if (error)
    return (
      <p style={{ textAlign: "center", marginTop: "50px", color: "red" }}>
        {error}
      </p>
    );

  return (
    <div className="container">
      <h1>📊 Website Activity Dashboard</h1>

      {/* ================= KPI CARDS ================= */}
      <div className="kpi-grid">
        <div className="kpi-card">
          <h3>Total Time Spent</h3>
          <p>
            {hours} hr {mins} min
          </p>
        </div>

        <div className="kpi-card">
          <h3>Websites Visited</h3>
          <p>{totalSites}</p>
        </div>

        <div className="kpi-card">
          <h3>Most Used Site</h3>
          <p>{mostUsedSite}</p>
        </div>

        <div className="kpi-card">
          <h3>Total Sessions</h3>
          <p>{totalSessions}</p>
        </div>
      </div>

      {/* ================= CHARTS ================= */}
      <div className="card">
        <h2>Daily Usage (Bar)</h2>
        {summary.length > 0 ? (
          <UsageBarChart data={summary} />
        ) : (
          <p>No summary data available</p>
        )}
      </div>

      <div className="card">
        <h2>Usage Share (Pie)</h2>
        {summary.length > 0 ? (
          <UsagePieChart data={summary} />
        ) : (
          <p>No summary data available</p>
        )}
      </div>

      <div className="card">
        <h2>📱 App Activity</h2>
        {sessions.length > 0 ? (
          <ActivityList sessions={sessions} />
        ) : (
          <p>No session data available</p>
        )}
      </div>
    </div>
  );
}
